<script setup lang="ts">
import {computed,ref} from 'vue'
import {useStudio} from './studioContext'
import AppIcon from './AppIcon.vue'
const props=defineProps<{page:string,target?:string,task?:string}>(),s=useStudio(),working=ref(false),choosing=ref(false),selected=ref<string[]>([])
const info=computed(()=>s.checklist.value.pages?.find((p:any)=>p.id===props.page)),job=computed(()=>s.p.value?.workspace.jobs?.find((j:any)=>j.family==='generation'&&j.scope===props.page))
const targets=computed(()=>s.entries(({characters:'persona',outline:'plot',clues:'clue',storyboards:'storyboard'} as any)[props.page]||'material'))
const hasMissing=computed(()=>!info.value?.complete||info.value?.done<info.value?.total)
function launch(){if(!hasMissing.value&&props.page!=='library'){choosing.value=!choosing.value;return}void s.generateStep(props.page,props.target?[props.target]:[],!hasMissing.value,props.task)}
const label=computed(()=>({library:'整理资料',outline:'生成剧本大纲',clues:'整理线索',characters:'生成人物对话设定',storyboards:'生成分镜提示词'} as any)[props.page])
async function control(action:string){working.value=true;try{await s.api(`/projects/${s.p.value.id}/studio/generation-batches/${job.value.id}/${action}`,'POST',{version:s.p.value.version,requestId:crypto.randomUUID()});await s.syncLatest()}catch(e:any){s.error.value=e.message}finally{working.value=false}}
</script>
<template><div class="generation-control"><button class="primary" :disabled="working||s.generating.value||!s.p.value||info?.canGenerate===false" :title="info?.blocker||''" @click="launch"><AppIcon name="ai" :size="15"/>{{!hasMissing?(page==='library'?'重新整理资料':'选择重新生成'):info?.done?'生成未完成内容':label}}<small>{{!hasMissing?'重新生成':info?.done?'补充生成':'首次生成'}}</small></button><div v-if="choosing" class="regeneration-selection"><label v-for="item in targets"><input type="checkbox" :value="item.id" v-model="selected">{{s.title(item)}}</label><button :disabled="!selected.length||s.generating.value" @click="s.generateStep(page,selected,true);choosing=false"><AppIcon name="ai" :size="14"/>重新生成选中内容</button></div><template v-if="job"><span v-if="['queued','running'].includes(job.state)" role="status">{{job.progress}} · {{job.steps.filter((v:any)=>v.state==='completed').length}}/{{job.steps.length}}</span><button v-if="['queued','running'].includes(job.state)" @click="control('cancel')">取消任务</button><template v-else-if="['failed','interrupted','partial'].includes(job.state)"><button :disabled="working||s.generating.value" @click="control('continue')">继续未完成项</button><small>{{job.error||'部分结果供你选择，其他内容可继续使用'}}</small></template></template></div></template>
<style scoped>.generation-control{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}.generation-control .primary{display:flex;align-items:center;gap:7px}.generation-control .primary svg{color:#ebca72}.generation-control small,.generation-control>span{font-size:11px;color:#909995}.generation-control .primary small{color:#dbe6e1;font-size:10px}</style>
